315	  void set_reset_vector(size_t hart, uint64_t addr)
316	  {
317	    if (hart >= platform.reset_vector.size()) {
318	      spdlog::critical("hart {} out of range (max {})", hart,
319	                       platform.reset_vector.size() - 1);
320	      std::exit(EXIT_FAILURE);
321	    }
322	    platform.reset_vector[hart].write(addr);
323	  }
