325	  void load_image(const std::string& path, MEM_TYPE type)
326	  {
327	    switch (type) {
328	    case MEM_TYPE::ILM:
329	      if constexpr (requires { cpu.set_ilm({}); }) {
330	        read_binary_file(path, [this](const auto& data) { cpu.set_ilm(data); });
331	      } else {
332	        throw std::runtime_error(
333	          "CPU does not support ILM - cannot load ILM ROM image");
334	      }
335	      break;
336	
337	    case MEM_TYPE::DLM:
338	      if constexpr (requires { cpu.set_dlm({}); }) {
339	        read_binary_file(path, [this](const auto& data) { cpu.set_dlm(data); });
340	      } else {
341	        throw std::runtime_error(
342	          "CPU does not support DLM - cannot load DLM ROM image");
343	      }
344	      break;
345	
346	    case MEM_TYPE::RAM:
347	      read_binary_file(path, [this](const auto& data) {
348	        if (data.size() > platform.main_memory.data.size())
349	          throw std::runtime_error("RAM image size exceeds main memory size");
350	        std::copy(data.begin(), data.end(), platform.main_memory.data.begin());
351	      });
352	      break;
353	
354	    default:
355	      throw std::runtime_error("Unknown memory type");
356	    }
357	  }
