359	  void reset()
360	  {
361	    static constexpr int core_num = CPU::NDS_NHART;
362	    static constexpr int reset_val = (1 << core_num) - 1;
363	
364	    platform.resetn.write(0);
365	    auto saved = context_config;
366	    context_config = {};
367	    this->run(1);
368	    context_config = saved;
369	
370	    for (size_t i = 0; i < platform.reset_vector.size(); ++i)
371	      spdlog::info("hart {} reset vector: {:#x}", i,
372	                   (uint64_t) platform.reset_vector[i].read());
373	
374	    platform.resetn.write(reset_val);
375	
376	    if (context_config.continue_from)
377	      restore_context(context_config.dir);
378	  }
