380	  int run(const uint64_t max_cycles = std::numeric_limits<uint64_t>::max())
381	  {
382	    auto sa = memzeroed<struct sigaction>();
383	    sa.sa_handler = sigint_handler;
384	    sigemptyset(&sa.sa_mask);
385	
386	    auto oact = memzeroed<struct sigaction>();
387	    if (sigaction(SIGINT, &sa, &oact) == -1)
388	      perror("sigaction");
389	
390	    const auto restore_sigint = std::experimental::scope_exit{[&] {
391	      if (sigaction(SIGINT, &oact, nullptr) == -1)
392	        perror("sigaction");
393	    }};
394	
395	    // wait for debugger connections
396	    while (dtm_debug && !dtm.is_connected()) {
397	      dtm.try_accept_socket();
398	      if (ctrlc != 0) {
399	        return 130;
400	      }
401	      sleep(1);
402	    }
403	
404	    [[maybe_unused]]
405	    bool ctx_resuming = context_config.continue_from;
406	    [[maybe_unused]]
407	    bool ctx_triggered = false;
408	
409	    for (auto n = uint64_t{0}; n < max_cycles; ++n) {
410	
411	      if (ctx_resuming) [[unlikely]] {
412	        // Pull up PLIC interrupt signal at the first cycle of the resume
413	        platform.int_trigger.write(1);
414	        ctx_resuming = false;
415	        ctx_triggered = true;
416	      }
417	
418	      sc_core::sc_start(platform.clk.period());
419	
420	      trace_.on_cycle(cpu);
421	
422	      if (hybrid_handoff_ || hybrid_icount_handoff_) [[unlikely]] {
423	        if (auto code = check_hybrid_handoff(); code) return *code;
424	      }
425	
426	      if (trace_.pipeview_wants_exit()) {
427	        spdlog::info("Pipeline viewer requested exit (Kanata loop window complete)");
428	        return 0;
429	      }
430	
431	      if (context_config.save_on_wfi && platform.wfi_signal.read() == true)
432	        [[unlikely]]
433	      {
434	        context_config.save(platform, cpu);
435	        spdlog::info("User save context");
436	        return 0;
437	      }
438	
439	      if (ctrlc != 0) {
440	        ctrlc = 0;
441	        spdlog::info("Ctrl+C PC: {:x}", get_current_pc());
442	        trace_.log_committed_pcs(cpu);
443	        return 130;
444	      }
445	
446	      if (ctx_triggered) [[unlikely]] {
447	        // Pull down the interrupt signal after 1 cycle
448	        platform.int_trigger.write(0);
449	        ctx_triggered = false;
450	      }
451	
452	      if (platform.sim_control.exits >= 0) {
453	        spdlog::info("sim_control: got exit {}, stopping",
454	                     platform.sim_control.exits);
455	        spdlog::info("Exit PC: {:x}", get_current_pc());
456	        trace_.log_committed_pcs(cpu);
457	        return platform.sim_control.exits;
458	      }
459	
460	      if (this->cpu.contextp()->gotFinish())
461	        return 0;
462	
463	      spdlog::trace("PC: {:x}", get_current_pc());
464	    }
465	    return 0;
466	  }
