468	  uint64_t get_current_pc()
469	  {
470	    if constexpr (requires { cpu.get_current_pc(); }) {
471	      return cpu.get_current_pc();
472	    }
473	    return std::numeric_limits<uint64_t>::max();
474	  }
475	
476	  auto check_hybrid_handoff() -> std::optional<int>
477	  {
478	    if constexpr (!requires { cpu.get_committed_pc(); }) {
479	      return std::nullopt;
480	    } else {
481	      const auto committed = cpu.get_committed_pc();
482	      if (committed.empty()) return std::nullopt;
483	      auto gpr_probe = [&](uint8_t r) -> uint64_t {
484	        if constexpr (requires { cpu.get_gpr(r); }) {
485	          return cpu.get_gpr(r);
486	        }
487	        return 0;
488	      };
489	      for (const auto pc: committed[0]) {
490	        auto state = std::optional<hybrid_state_v1>{};
491	        if (hybrid_handoff_)
492	          state = hybrid_handoff_->on_retire(pc, gpr_probe);
493	        else if (hybrid_icount_handoff_)
494	          state = hybrid_icount_handoff_->on_retire(pc, gpr_probe);
495	        if (state) {
496	          // V-register merge: the fixture's vsim-phase epilogue is expected
497	          // to have run vse8.v v0..v31 to scratch RAM before the exit
498	          // trigger fired. Read those bytes back into state.vreg[] so the
499	          // gdbstub-driven QEMU 2 restore sees vsim's actual values, not
500	          // QEMU 1's stale snapshot.
501	          if ((state->flags & HYBRID_FLAG_V) != 0u) {
502	            hybrid::read_v_from_scratch(
503	              *state,
504	              std::span<const uint8_t>{platform.main_memory.data.data(),
505	                                       platform.main_memory.data.size()},
506	              platform.main_memory.region.base_address);
507	          }
508	          spdlog::info("hybrid handoff: drained at pc=0x{:x}, writing {}",
509	                       pc, hybrid_state_path_);
510	          std::ofstream f(hybrid_state_path_, std::ios::binary);
511	          f.write(reinterpret_cast<const char*>(&*state), sizeof(*state));
512	          return hybrid::kExitHandoffToQemu;
513	        }
514	      }
515	      return std::nullopt;
516	    }
517	  }
