127	  /// Start instruction without PC (OoO: PC unknown at issue time).
128	  /// Use label_insn() later to back-fill the PC at commit.
129	  void start_insn_deferred(uint64_t id)
130	  {
131	    if (!enabled_)
132	      return;
133	    inflight_.insert(id);
134	    *output_ << fmt::format("I\t{}\t{}\t0\n", id, id);
135	  }
136	
137	  /// Back-fill label for a deferred instruction (OoO commit).
138	  void label_insn(uint64_t id, uint64_t pc,
139	                  std::string_view suffix = "")
140	  {
141	    id_to_pc_[id] = pc;
142	    if (!is_inflight(id))
143	      return;
144	    auto it = code_map_.find(pc);
145	    auto code = (it != code_map_.end()) ? it->second : std::string{};
146	    if (suffix.empty())
147	      *output_ << fmt::format("L\t{}\t0\t{:#x}: {}\n", id, pc, code);
148	    else
149	      *output_ << fmt::format("L\t{}\t0\t{:#x}: {} [{}]\n", id, pc, code,
150	                              suffix);
151	  }
