197	  /// Load objdump -d output to populate PC→assembly map.
198	  void load_objdump(const std::string& filename)
199	  {
200	    std::ifstream fin(filename);
201	    if (!fin.is_open()) {
202	      spdlog::warn("Failed to open objdump file: {}", filename);
203	      return;
204	    }
205	    std::regex code_regex(R"(^\s*([0-9a-f]+):\t([0-9a-f ]+)\t(.+)$)");
206	    std::string line;
207	    while (std::getline(fin, line)) {
208	      std::smatch match;
209	      if (std::regex_match(line, match, code_regex)) {
210	        auto pc = std::stoull(match[1].str(), nullptr, 16);
211	        auto asm_code = match[3].str();
212	        // Replace tabs with double spaces (same as Python)
213	        for (auto pos = asm_code.find('\t'); pos != std::string::npos;
214	             pos = asm_code.find('\t', pos))
215	        {
216	          asm_code.replace(pos, 1, "  ");
217	          pos += 2;
218	        }
219	        code_map_[pc] = std::move(asm_code);
220	      }
221	    }
222	    spdlog::info("Loaded {} disassembly entries from {}", code_map_.size(),
223	                 filename);
224	  }
