233	private:
234	  /// On the first start_insn(start_pc) after skip_iters end_pc retires,
235	  /// flip the gate open and realign the on-disk Konata cycle counter to
236	  /// the simulator's total_cycles_ so the recorded window draws at the
237	  /// correct absolute time.
238	  void maybe_open_window(uint64_t pc)
239	  {
240	    if (enabled_ || !gate_)
241	      return;
242	    if (pc != gate_->start_pc)
243	      return;
244	    if (end_retired_ < gate_->skip_iters)
245	      return;
246	    enabled_ = true;
247	    auto delta = total_cycles_ - start_cycle_;
248	    start_cycle_ = total_cycles_;
249	    if (delta > 0)
250	      *output_ << "C\t" << delta << '\n';
251	    spdlog::info(
252	      "Kanata loop gate: window opens at cycle {} (pc {:#x})",
253	      total_cycles_, pc);
254	  }
