256	  bool is_inflight(uint64_t id) const { return inflight_.count(id) != 0; }
257	
258	  bool remove_inflight(uint64_t id) { return inflight_.erase(id) > 0; }
259	
260	  void write_header()
261	  {
262	    *output_ << "Kanata\t0004\n";
263	    *output_ << "C=\t0\n";
264	  }
