266	  /// Called from retire_insn(). Looks up the PC for `id`, advances the
267	  /// iteration counter when it matches the gate's end_pc, and trips the
268	  /// window_complete_ flag once skip_iters + record_iters retires have
269	  /// been observed. Window opening is handled in start_insn().
270	  void on_retire_pc(uint64_t id, bool /*emitted*/)
271	  {
272	    if (!gate_) {
273	      id_to_pc_.erase(id);
274	      return;
275	    }
276	    auto it = id_to_pc_.find(id);
277	    if (it == id_to_pc_.end())
278	      return;
279	    auto pc = it->second;
280	    id_to_pc_.erase(it);
281	    if (pc != gate_->end_pc)
282	      return;
283	
284	    ++end_retired_;
285	    if (enabled_
286	        && end_retired_ == gate_->skip_iters + gate_->record_iters)
287	    {
288	      auto window_cycles = total_cycles_ - start_cycle_;
289	      spdlog::info(
290	        "Kanata loop window [pc {:#x}..{:#x}]: {} iters, {} insns, {} "
291	        "cycles, IPC={:.3f}",
292	        gate_->start_pc, gate_->end_pc, gate_->record_iters,
293	        recorded_insns_, window_cycles,
294	        window_cycles ? double(recorded_insns_) / double(window_cycles)
295	                      : 0.0);
296	      flush_all();
297	      window_complete_ = true;
298	    }
299	  }
